import { useEffect } from 'react'

export interface ErrorPageProps {
  error: Error & { digest?: string }
  retry: () => void
}

// Replaces pages/_error.js for errors thrown while rendering route segments.
// 404s are handled by app/not-found.tsx; status codes are no longer passed
// via getInitialProps.
export default function Error({ error, retry }: ErrorPageProps) {
  useEffect(() => {
    console.error(error)
  }, [error])

  return (
    <>
      <title>Error - My Blog</title>

      <div className="error-page">
        <h1>An error occurred</h1>
        <p>Sorry, something went wrong.</p>
        <button onClick={() => retry()}>Try again</button>
      </div>
    </>
  )
}

