import type { NextRequest } from 'next/server'

export interface ApiPost {
  id: number
  title: string
  content: string
  createdAt?: string
  updatedAt?: string
}

interface CreatePostBody {
  title?: unknown
  content?: unknown
}

// Unsupported methods automatically receive a 405 response from Next.js.

export function GET() {
  // Simulate fetching posts
  const posts: ApiPost[] = [
    { id: 1, title: 'First Post', content: 'This is the first post' },
    { id: 2, title: 'Second Post', content: 'This is the second post' },
  ]

  return Response.json(posts)
}

export async function POST(request: NextRequest) {
  const body = (await request.json().catch(() => ({}))) as CreatePostBody | null
  const title = body?.title
  const content = body?.content

  if (typeof title !== 'string' || typeof content !== 'string' || !title || !content) {
    return Response.json(
      { error: 'Title and content are required' },
      { status: 400 }
    )
  }

  // Simulate creating a post
  const newPost: ApiPost = {
    id: Date.now(),
    title,
    content,
    createdAt: new Date().toISOString(),
  }

  return Response.json(newPost, { status: 201 })
}

