import { cache } from 'react'

const API_URL = 'https://jsonplaceholder.typicode.com'

/** Post shape returned by the JSONPlaceholder API. */
export interface Post {
  userId: number
  id: number
  title: string
  body: string
}

/** Comment shape returned by the JSONPlaceholder API. */
export interface Comment {
  postId: number
  id: number
  name: string
  email: string
  body: string
}

async function fetchJson<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(`${API_URL}${path}`, init)
  if (!res.ok) {
    throw new Error(`Request to ${path} failed with status ${res.status}`)
  }
  return (await res.json()) as T
}

export function getPosts(
  options: { limit?: number; init?: RequestInit } = {}
): Promise<Post[]> {
  const query = options.limit ? `?_limit=${options.limit}` : ''
  return fetchJson<Post[]>(`/posts${query}`, options.init)
}

/**
 * Returns the post or `null` if it doesn't exist.
 * Wrapped in `cache` so `generateMetadata` and the page share one request.
 */
export const getPost = cache(async (id: string): Promise<Post | null> => {
  const res = await fetch(`${API_URL}/posts/${encodeURIComponent(id)}`)
  if (res.status === 404) return null
  if (!res.ok) {
    throw new Error(`Request for post ${id} failed with status ${res.status}`)
  }
  return (await res.json()) as Post
})

export function getComments(postId: string): Promise<Comment[]> {
  return fetchJson<Comment[]>(`/posts/${encodeURIComponent(postId)}/comments`)
}

