import { getComments, getPost, getPosts } from '@/lib/posts'

// Replaces getStaticProps `revalidate: 300` (5 minutes).
export const revalidate = 300

// Replaces getStaticPaths `fallback: 'blocking'`: params not returned by
// generateStaticParams are rendered on demand and then cached.
export const dynamicParams = true

// Replaces getStaticPaths.
export async function generateStaticParams(): Promise<{ id: string }[]> {
  const posts = await getPosts()
  return posts.slice(0, 10).map((post) => ({ id: post.id.toString() }))
}

export async function generateMetadata({
  params,
}: PageProps<'/blog/[id]'>): Promise<Metadata> {
  const { id } = await params
  const post = await getPost(id)
  if (!post) return {}

  const description = post.body.substring(0, 160)
  return {
    title: `${post.title} - My Blog`,
    description,
    openGraph: {
      title: post.title,
      description,
    },
  }
}

export default async function BlogPost({ params }: PageProps<'/blog/[id]'>) {
  const { id } = await params

  // Replaces `return { notFound: true }` from getStaticProps.
  const [post, comments] = await Promise.all([
    getPost(id),
    getComments(id),
  ]).catch(() => notFound())
  if (!post) notFound()

  return (
    <article>
      <BackButton>← Back</BackButton>

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

