import type { NextRequest } from 'next/server'

export interface ApiPost {
  id: number
  title: string
  content: string
  createdAt?: string
  updatedAt?: string
}

interface CreatePostBody {
  title?: unknown
  content?: unknown
}

// Unsupported methods automatically receive a 405 response from Next.js.

export function GET() {
  // Simulate fetching posts
  const posts: ApiPost[] = [
    { id: 1, title: 'First Post', content: 'This is the first post' },
    { id: 2, title: 'Second Post', content: 'This is the second post' },
  ]

  return Response.json(posts)
}

export async function POST(request: NextRequest) {
  const body = (await request.json().catch(() => ({}))) as CreatePostBody | null
  const title = body?.title
  const content = body?.content

  if (typeof title !== 'string' || typeof content !== 'string' || !title || !content) {
    return Response.json(
      { error: 'Title and content are required' },
      { status: 400 }
    )
  }

  // Simulate creating a post
  const newPost: ApiPost = {
    id: Date.now(),
    title,
    content,
    createdAt: new Date().toISOString(),
  }

  return Response.json(newPost, { status: 201 })
}

import type { NextRequest } from 'next/server'
import type { ApiPost } from '../route'

interface UpdatePostBody {
  title?: unknown
  content?: unknown
}

// Unsupported methods automatically receive a 405 response from Next.js.

export async function GET(
  _request: NextRequest,
  { params }: RouteContext<'/api/posts/[id]'>
) {
  const { id } = await params

  // Simulate fetching a single post
  const post: ApiPost = {
    id: parseInt(id, 10),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return Response.json(post)
}

export async function PUT(
  request: NextRequest,
  { params }: RouteContext<'/api/posts/[id]'>
) {
  const { id } = await params
  const body = (await request.json().catch(() => ({}))) as UpdatePostBody | null
  const title = typeof body?.title === 'string' ? body.title : ''
  const content = typeof body?.content === 'string' ? body.content : ''

  // Simulate updating a post
  const updatedPost: ApiPost = {
    id: parseInt(id, 10),
    title: title || `Post ${id}`,
    content: content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return Response.json(updatedPost)
}

export async function DELETE(
  _request: NextRequest,
  { params }: RouteContext<'/api/posts/[id]'>
) {
  const { id } = await params

  // Simulate deleting a post
  return Response.json({ message: `Post ${id} deleted successfully` })
}

